def _state_anchors_archive_hash(generation: int, records: list) -> str:
    """SHA-256 over the canonical JSON bytes of every field but ``hash``."""
    body = {
        "v": STATE_ANCHORS_VERSION,
        "generation": generation,
        "records": records,
